def check_collection_sizes_and_array_length_comparisons_sense(node):
    return any(node['property_path'] == path and any(op in forb_ops for op in node['children'][1]['expression']['operators']) for path, forb_ops in FORBIDDEN_PATHS.items())

FORBIDDEN_PATHS = {
    ('len', 'call', 'arguments', '0'),
    ('len', 'call', 'arguments', '1'),
    ('len', 'call', 'key'),
    ('len', 'call', 'args'),
    ('len', 'attribute'),
    ('len', 'subscript'),
    ('len', 'binary_op'),
    ('len', 'unary_op')
}
